insert into passages (id, text, difficulty_level, b, active) values
('b57d36b4-cf91-486d-acf0-b779844a0912', 'Microplastics, tiny plastic fragments less than five millimeters in size, have become one of the most widespread forms of pollution on the planet, found everywhere from remote mountain snow to the deepest ocean trenches. These particles originate from a variety of sources, including the breakdown of larger plastic waste, synthetic fibers shed from clothing during washing, and tiny plastic beads once commonly used in cosmetic products. Because microplastics are so small and chemically stable, they persist in the environment for extremely long periods and are readily ingested by marine organisms, from plankton to whales. Researchers are still working to understand the full health implications of microplastic exposure for both wildlife and humans, since these particles have now been detected in human blood, lung tissue, and even placentas. While some studies suggest potential links to inflammation and cellular damage, scientists caution that more research is needed before drawing firm conclusions about long-term health effects. In the meantime, several countries have banned microbeads in cosmetics, and researchers continue developing filtration technologies aimed at capturing microplastics before they enter waterways.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('e05efdcf-cfb3-4510-a1ff-ee44dcd9342b', 'sentence_completion', 'The senator''s speech was carefully ___ to avoid alienating any part of her constituency.', NULL, '[{"id": "c", "text": "crafted"}, {"id": "d", "text": "ignored"}, {"id": "b", "text": "abandoned"}, {"id": "a", "text": "destroyed"}]'::jsonb, 0, '{"strategy": "avoid alienating any part of her constituency = להימנע מהרחקת חלק מהבוחרים. איזה סוג נאום נמנע מכך?", "correct_reason": "crafted = מנוסח בקפידה. נאום מנוסח בקפידה נמנע מפגיעה בקהל.", "options_analysis": ["נכון! crafted = מנוסח בקפידה — מתאים לנמנעות מהרחקת בוחרים", "ignored = הוזנח — לא רלוונטי", "abandoned = ננטש — לא רלוונטי לנאום שנישא", "destroyed = הושמד — לא רלוונטי לנאום"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('ca8b36ae-bd58-4fc2-aab2-5fba5bf432e2', 'sentence_completion', 'The company''s aggressive expansion strategy ___ significant financial risk.', NULL, '[{"id": "a", "text": "prevented"}, {"id": "d", "text": "entailed"}, {"id": "b", "text": "avoided"}, {"id": "c", "text": "eliminated"}]'::jsonb, 1, '{"strategy": "aggressive expansion = הרחבה אגרסיבית. מה מלווה אסטרטגיה אגרסיבית?", "correct_reason": "entailed = כרכה בחובה/גררה. הרחבה אגרסיבית כרוכה בסיכון.", "options_analysis": ["prevented = מנעה — הפוך מהיגיון האסטרטגיה", "נכון! entailed = כרכה — הרחבה אגרסיבית כרוכה בסיכון", "avoided = נמנעה מ- — הפוך, אגרסיביות לא נמנעת מסיכון", "eliminated = חיסלה — הפוך מאסטרטגיה מסוכנת"]}', 1.5, 1.0, 0.25, 4, 'ai', NULL, true),
('a88dcde0-5ad8-4369-b152-569e8f44126e', 'sentence_completion', 'The panel''s ___ approach to the investigation left no stone unturned.', NULL, '[{"id": "d", "text": "superficial"}, {"id": "b", "text": "careless"}, {"id": "c", "text": "meticulous"}, {"id": "a", "text": "hasty"}]'::jsonb, 2, '{"strategy": "left no stone unturned = לא השאיר אבן שלא נהפכה. איזו גישה כזו?", "correct_reason": "meticulous = קפדנית/דקדקנית. חקירה יסודית לא משאירה שום דבר בלי בדיקה.", "options_analysis": ["superficial = שטחית — הפוך מיסודיות", "careless = חסרת זהירות — הפוך מיסודיות", "נכון! meticulous = קפדנית — מתאים ל''no stone unturned''", "hasty = נחפזת — הפוך מיסודיות"]}', 0.94, 1.0, 0.25, 4, 'ai', NULL, true),
('fce54173-6143-4bb4-95b1-ae488b5a1410', 'sentence_completion', 'The board''s decision to ___ the CEO came after months of declining performance.', NULL, '[{"id": "a", "text": "promote"}, {"id": "d", "text": "celebrate"}, {"id": "b", "text": "reward"}, {"id": "c", "text": "dismiss"}]'::jsonb, 3, '{"strategy": "after months of declining performance = אחרי חודשי ירידה בביצועים. מה עושה דירקטוריון למנכ''ל שביצועיו יורדים?", "correct_reason": "dismiss = לפטר. ביצועים יורדים מובילים בד''כ לפיטורים.", "options_analysis": ["promote = לקדם — הפוך, ביצועים יורדים לא מובילים לקידום", "celebrate = לחגוג — לא רלוונטי", "reward = לתגמל — הפוך מביצועים גרועים", "נכון! dismiss = לפטר — תגובה הגיונית לירידה ממושכת"]}', 0.92, 1.0, 0.25, 4, 'ai', NULL, true),
('5d56ff2e-cacf-47a6-a570-6ed39a28b1b4', 'sentence_completion', 'The scientist''s hypothesis was ___ by subsequent experiments.', NULL, '[{"id": "a", "text": "validated"}, {"id": "d", "text": "ignored"}, {"id": "c", "text": "invented"}, {"id": "b", "text": "forgotten"}]'::jsonb, 0, '{"strategy": "subsequent experiments = ניסויים מאוחרים יותר. מה עושים ניסויים להשערה?", "correct_reason": "validated = אוששה/אומתה. ניסויים מאשרים או מפריכים השערות.", "options_analysis": ["נכון! validated = אוששה — פעולה טבעית של ניסויים על השערה", "ignored = הוזנחה — לא רלוונטי", "invented = הומצאה — לא רלוונטי לתהליך מדעי", "forgotten = נשכחה — לא רלוונטי לתהליך מדעי"]}', 1.56, 1.0, 0.25, 4, 'ai', NULL, true),
('6a7153f9-e304-4e6c-a5d9-c89b62b8041e', 'sentence_completion', 'The politician''s ___ remarks sparked outrage among voters.', NULL, '[{"id": "b", "text": "measured"}, {"id": "c", "text": "inflammatory"}, {"id": "d", "text": "cautious"}, {"id": "a", "text": "diplomatic"}]'::jsonb, 1, '{"strategy": "sparked outrage = הצית זעם. איזה סוג הערות מצית זעם?", "correct_reason": "inflammatory = מסית/מלבה. הערות כאלה מעוררות זעם.", "options_analysis": ["measured = מדודה — הפוך מהצתת זעם", "נכון! inflammatory = מסיתה — מסבירה זעם ציבורי", "cautious = זהירה — הפוך מהצתת זעם", "diplomatic = דיפלומטית — הפוך מהצתת זעם"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('84c874c8-0f72-49b1-a20f-014cdc65c2de', 'sentence_completion', 'The company''s financial troubles were largely ___ by poor management decisions.', NULL, '[{"id": "b", "text": "prevented"}, {"id": "d", "text": "solved"}, {"id": "c", "text": "exacerbated"}, {"id": "a", "text": "ignored"}]'::jsonb, 2, '{"strategy": "financial troubles...largely ___ by = קשיים כלכליים...בעיקר...ע''י. מה עושות החלטות ניהול גרועות לקשיים?", "correct_reason": "exacerbated = החמירו. ניהול גרוע מחמיר קשיים כלכליים.", "options_analysis": ["prevented = נמנעו — הפוך מ''troubles''", "solved = נפתרו — הפוך מהחלטות ניהול גרועות", "נכון! exacerbated = החמירו — הסבר הגיוני לקשיים כלכליים", "ignored = הוזנחו — לא מסביר את הקשיים עצמם"]}', 1.19, 1.0, 0.25, 4, 'ai', NULL, true),
('cc550b63-c589-4b9f-880b-df08fea1e0c4', 'sentence_completion', 'The museum''s latest exhibit ___ visitors with its innovative use of technology.', NULL, '[{"id": "b", "text": "confused"}, {"id": "c", "text": "bored"}, {"id": "d", "text": "repelled"}, {"id": "a", "text": "captivated"}]'::jsonb, 3, '{"strategy": "innovative use of technology = שימוש חדשני בטכנולוגיה. מה עושה תערוכה חדשנית למבקרים?", "correct_reason": "captivated = ריתקה. תערוכה חדשנית מרתקת מבקרים.", "options_analysis": ["confused = בלבלה — לא מתאר הצלחה", "bored = שיעממה — הפוך מחדשנות מוצלחת", "repelled = דחתה — הפוך מהצלחה", "נכון! captivated = ריתקה — תוצאה טבעית של תערוכה חדשנית"]}', 1.01, 1.0, 0.25, 4, 'ai', NULL, true),
('9f15d8d2-78c0-4ed2-bbee-44551a5ee592', 'sentence_completion', 'The report''s ___ conclusions left little room for alternative interpretations.', NULL, '[{"id": "b", "text": "definitive"}, {"id": "d", "text": "tentative"}, {"id": "c", "text": "ambiguous"}, {"id": "a", "text": "vague"}]'::jsonb, 0, '{"strategy": "left little room for alternative interpretations = השאיר מעט מקום לפרשנויות חלופיות. איזה סוג מסקנות?", "correct_reason": "definitive = חד-משמעיות/סופיות. מסקנות חד-משמעיות לא משאירות מקום לפרשנות אחרת.", "options_analysis": ["נכון! definitive = חד-משמעיות — מתאים לחוסר מקום לפרשנות אחרת", "tentative = זמניות/מהוססות — הפוך מחד-משמעיות", "ambiguous = דו-משמעיות — הפוך, משאירות מקום לפרשנות", "vague = מעורפלות — הפוך, משאירות מקום לפרשנות"]}', 0.94, 1.0, 0.25, 4, 'ai', NULL, true),
('84369d1a-b2b9-4f2b-a785-1e37bfe44b35', 'sentence_completion', 'The negotiator''s willingness to ___ ultimately led to a successful agreement.', NULL, '[{"id": "d", "text": "withdraw"}, {"id": "a", "text": "compromise"}, {"id": "c", "text": "dominate"}, {"id": "b", "text": "refuse"}]'::jsonb, 1, '{"strategy": "led to a successful agreement = הוביל להסכם מוצלח. מה מוביל להסכם מוצלח במו''מ?", "correct_reason": "compromise = להתפשר. נכונות להתפשר מובילה להסכם.", "options_analysis": ["withdraw = לסגת — הפוך, נסיגה לא מובילה להסכם", "נכון! compromise = להתפשר — מוביל טבעי להסכם מוצלח", "dominate = לשלוט — פחות מוביל להסכם הדדי", "refuse = לסרב — הפוך מהיגיון של הסכם מוצלח"]}', 1.09, 1.0, 0.25, 4, 'ai', NULL, true),
('1ff2ef1d-c999-43b4-913d-f9b24941178d', 'sentence_completion', 'The economist''s ___ forecast turned out to be remarkably accurate.', NULL, '[{"id": "c", "text": "careless"}, {"id": "a", "text": "random"}, {"id": "d", "text": "bold"}, {"id": "b", "text": "reckless"}]'::jsonb, 2, '{"strategy": "turned out to be remarkably accurate = התבררה כמדויקת להפליא. איזו תחזית מתגלה כמדויקת?", "correct_reason": "bold = נועזת. תחזית נועזת (יוצאת דופן) שהתבררה נכונה מרשימה יותר.", "options_analysis": ["careless = חסרת זהירות — סותר תחזית מדויקת מבוססת", "random = אקראית — סותר תחזית מקצועית מבוססת", "נכון! bold = נועזת — תחזית נועזת שהתבררה מדויקת מרשימה", "reckless = פזיזה — פחות מתאים לתחזית שהתבררה כמדויקת"]}', 1.33, 1.0, 0.25, 4, 'ai', NULL, true),
('b9a7608f-4dbc-47cf-8ce1-96aa92f7a1b2', 'sentence_completion', 'The court''s ruling ___ a precedent that would affect similar cases for decades.', NULL, '[{"id": "c", "text": "forgot"}, {"id": "b", "text": "erased"}, {"id": "a", "text": "ignored"}, {"id": "d", "text": "established"}]'::jsonb, 3, '{"strategy": "would affect similar cases for decades = ישפיע על תיקים דומים במשך עשורים. מה עשתה הפסיקה?", "correct_reason": "established = קבעה. פסיקה משפיעה קובעת תקדים.", "options_analysis": ["forgot = שכחה — לא רלוונטי לפסיקה", "erased = מחקה — הפוך מיצירת תקדים", "ignored = התעלמה מ- — סותר את ההשפעה שמתוארת", "נכון! established = קבעה — מתאים ליצירת השפעה ארוכת טווח"]}', 0.98, 1.0, 0.25, 4, 'ai', NULL, true),
('dbdb6f66-a1f1-45b0-b940-5ff52c9dc72e', 'restatement', 'The more resources a company invests in training, the more skilled its workforce becomes.', NULL, '[{"id": "b", "text": "Investing more in training leads to a more skilled workforce."}, {"id": "a", "text": "A company''s workforce becomes less skilled the more it invests in training."}, {"id": "d", "text": "Companies that invest less in training have more skilled workers."}, {"id": "c", "text": "Training investment has no effect on workforce skill."}]'::jsonb, 0, '{"strategy": "the more...the more = יחס ישר בין השקעה בהכשרה למיומנות.", "correct_reason": "אותו יחס ישר בדיוק.", "options_analysis": ["נכון! אותו יחס ישר בדיוק", "הפוך גמור — יותר השקעה מובילה ליותר מיומנות, לא פחות", "הפוך תפקידים — פחות השקעה לא מובילה ליותר מיומנות", "סותר את היחס המתואר במקור"]}', 1.1, 1.0, 0.25, 4, 'ai', NULL, true),
('68fb658e-91cc-4645-99c4-6c30b28833d0', 'restatement', 'Not only did the merger fail to increase profits, but it also damaged the company''s reputation.', NULL, '[{"id": "d", "text": "The merger increased profits and improved the company''s reputation."}, {"id": "a", "text": "The merger both failed to increase profits and harmed the company''s reputation."}, {"id": "c", "text": "The merger increased profits but harmed the reputation."}, {"id": "b", "text": "The merger had no effect on profits or reputation."}]'::jsonb, 1, '{"strategy": "not only...but also = לא רק...אלא גם. שתי תוצאות שליליות.", "correct_reason": "אותן שתי תוצאות שליליות בדיוק.", "options_analysis": ["הפוך גמור לשתי התוצאות", "נכון! אותן שתי תוצאות שליליות בדיוק", "סותר את החלק הראשון — הרווחים לא עלו", "סותר את שתי ההשפעות שתוארו"]}', 0.94, 1.0, 0.25, 4, 'ai', NULL, true),
('ba156515-b998-4d33-bf1e-14f04e0e49bd', 'restatement', 'Were it not for the timely intervention of the paramedics, the outcome could have been fatal.', NULL, '[{"id": "b", "text": "The paramedics had no role in the outcome at all."}, {"id": "a", "text": "The paramedics arrived too late to make any difference."}, {"id": "d", "text": "The paramedics'' timely intervention may have prevented a fatal outcome."}, {"id": "c", "text": "The outcome was fatal despite the paramedics'' intervention."}]'::jsonb, 2, '{"strategy": "תנאי היפותטי הפוך: לולא ההתערבות, התוצאה יכלה להיות קטלנית.", "correct_reason": "המשמעות הנכונה: ההתערבות בזמן מנעה תוצאה קטלנית.", "options_analysis": ["סותר את התפקיד המרכזי שמתואר במקור", "סותר ''timely intervention'' — הם הגיעו בזמן", "נכון! ההתערבות בזמן מנעה תוצאה קטלנית — המשמעות הנכונה של התנאי ההפוך", "סותר ''could have been fatal'' — התוצאה לא הייתה קטלנית בפועל"]}', 1.24, 1.0, 0.25, 4, 'ai', NULL, true),
('36d69275-9e52-44fd-bf2b-810acd1f8e45', 'restatement', 'The longer the drought continued, the more severe the water shortage became.', NULL, '[{"id": "a", "text": "The drought had no connection to the water shortage."}, {"id": "d", "text": "The water shortage ended the drought."}, {"id": "b", "text": "The water shortage became less severe as the drought continued."}, {"id": "c", "text": "As the drought continued longer, the water shortage grew more severe."}]'::jsonb, 3, '{"strategy": "the longer...the more severe = יחס ישר בין משך הבצורת לחומרת המחסור.", "correct_reason": "אותו יחס ישר בדיוק.", "options_analysis": ["סותר את הקשר המפורש במקור", "סותר לגמרי את כיוון הסיבתיות", "הפוך גמור — משך ארוך יותר החמיר, לא הקל", "נכון! אותו יחס ישר בדיוק"]}', 1.53, 1.0, 0.25, 4, 'ai', NULL, true),
('0ac30a9f-e439-4477-af2c-22d72550954c', 'restatement', 'Not until the audit was completed did the fraud come to light.', NULL, '[{"id": "c", "text": "The audit revealed the fraud only after it was completed."}, {"id": "a", "text": "The fraud was discovered before the audit began."}, {"id": "b", "text": "No audit was ever conducted."}, {"id": "d", "text": "The fraud was never discovered."}]'::jsonb, 0, '{"strategy": "not until...did = רק אחרי...אז. תנאי הכרחי.", "correct_reason": "אותו תנאי הכרחי בדיוק.", "options_analysis": ["נכון! אותו תנאי הכרחי בדיוק: גילוי רק אחרי סיום הביקורת", "הפוך — הביקורת קדמה לגילוי, לא להפך", "סותר ''the audit was completed''", "סותר ''came to light'' — ההונאה כן התגלתה"]}', 1.05, 1.0, 0.25, 4, 'ai', NULL, true),
('77803ddf-c1c2-40c2-b1cc-27cf9ca0fea7', 'restatement', 'The committee''s recommendation, controversial though it was, ultimately shaped national policy.', NULL, '[{"id": "a", "text": "National policy was shaped before the recommendation was made."}, {"id": "c", "text": "Despite being controversial, the recommendation ended up shaping national policy."}, {"id": "d", "text": "The recommendation was rejected due to controversy."}, {"id": "b", "text": "The recommendation was uncontroversial and had no impact on policy."}]'::jsonb, 1, '{"strategy": "controversial though it was...shaped = שנוי במחלוקת אך עיצב. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["הופך את סדר האירועים", "נכון! אותה משמעות בדיוק: למרות המחלוקת, עיצבה מדיניות", "סותר ''ultimately shaped national policy''", "סותר ''controversial'' — הייתה שנויה במחלוקת"]}', 1.12, 1.0, 0.25, 4, 'ai', NULL, true),
('318706b1-ddef-454d-b1a3-ef0de5ecb584', 'restatement', 'So thoroughly did the auditors examine the accounts that no discrepancy went unnoticed.', NULL, '[{"id": "b", "text": "The auditors barely looked at the accounts."}, {"id": "c", "text": "Many discrepancies were missed by the auditors."}, {"id": "a", "text": "The auditors examined the accounts so carefully that every discrepancy was found."}, {"id": "d", "text": "The auditors refused to examine the accounts."}]'::jsonb, 2, '{"strategy": "so thoroughly...that = כה ביסודיות...עד ש-. תוצאה קיצונית.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''so thoroughly''", "סותר ''no discrepancy went unnoticed''", "נכון! אותה משמעות בדיוק: בדיקה כה יסודית שכל אי-התאמה נמצאה", "סותר ''did the auditors examine''"]}', 1.22, 1.0, 0.25, 4, 'ai', NULL, true),
('0dea4504-c03a-4f88-b2e5-f4532dbf206e', 'restatement', 'The vaccine''s effectiveness, while not absolute, significantly reduced hospitalization rates.', NULL, '[{"id": "c", "text": "Hospitalization rates increased after the vaccine was introduced."}, {"id": "b", "text": "The vaccine was completely effective in every case."}, {"id": "a", "text": "The vaccine had no effect on hospitalization rates."}, {"id": "d", "text": "Although not completely effective, the vaccine greatly reduced hospitalizations."}]'::jsonb, 3, '{"strategy": "while not absolute, significantly reduced = לא מוחלטת, אך הפחיתה משמעותית. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["הפוך — ''increased'' סותר ''reduced''", "סותר ''while not absolute'' — לא הייתה יעילות מוחלטת", "סותר ''significantly reduced hospitalization rates''", "נכון! אותה משמעות בדיוק: לא מושלם אך הפחית משמעותית"]}', 1.11, 1.0, 0.25, 4, 'ai', NULL, true),
('feed03a5-bdf4-40d2-bc41-012017176798', 'restatement', 'Little did the investors suspect that the company''s financial reports were fabricated.', NULL, '[{"id": "b", "text": "The investors had no idea the financial reports were fabricated."}, {"id": "d", "text": "The investors created the fabricated reports themselves."}, {"id": "a", "text": "The investors were fully aware the reports were fabricated."}, {"id": "c", "text": "The company''s reports were completely accurate."}]'::jsonb, 0, '{"strategy": "little did...suspect = כמעט לא חשדו. שלילה כפולה = חוסר מודעות.", "correct_reason": "אותה משמעות בדיוק של חוסר מודעות.", "options_analysis": ["נכון! אותה משמעות בדיוק: לא היה להם מושג שהדוחות מזויפים", "לא נאמר במקור שהמשקיעים יצרו את הדוחות", "הפוך גמור — ''little did suspect'' = לא היו מודעים כלל", "סותר ''fabricated'' — הדוחות היו מזויפים"]}', 1.17, 1.0, 0.25, 4, 'ai', NULL, true),
('a85652e4-fb0b-420e-b2b1-7c92783431fa', 'restatement', 'Had the warning signs been heeded, the collapse might have been avoided.', NULL, '[{"id": "b", "text": "There were no warning signs before the collapse."}, {"id": "d", "text": "The collapse occurred because the warning signs were ignored."}, {"id": "a", "text": "The collapse happened despite heeding the warning signs."}, {"id": "c", "text": "The warning signs were heeded, which prevented the collapse."}]'::jsonb, 1, '{"strategy": "תנאי שלישי הפוך: לא הקשיבו לאזהרות, ולכן קרתה הקריסה.", "correct_reason": "המשמעות ההפוכה הנכונה של התנאי השלישי.", "options_analysis": ["סותר ''had the warning signs been heeded'' — היו סימני אזהרה", "נכון! תנאי שלישי הפוך: התעלמות מהאזהרות גרמה לקריסה", "סותר את המשמעות ההפוכה של התנאי", "סותר לגמרי — במקור לא הקשיבו לאזהרות"]}', 1.31, 1.0, 0.25, 4, 'ai', NULL, true),
('12023044-0fee-4429-9656-b4c35515782d', 'restatement', 'The report''s findings, alarming as they were, prompted immediate policy changes.', NULL, '[{"id": "c", "text": "Policy changes were made before the report was published."}, {"id": "b", "text": "The findings were reassuring and led to no changes."}, {"id": "d", "text": "Alarming as they were, the findings led to immediate changes in policy."}, {"id": "a", "text": "Despite being alarming, the findings were ignored entirely."}]'::jsonb, 2, '{"strategy": "alarming as they were...prompted = מדאיגים ככל שהיו...הובילו. תוצאה למרות/בגלל.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הופך את סדר האירועים", "הפוך — ''reassuring'' סותר ''alarming''", "נכון! אותה משמעות בדיוק: ממצאים מדאיגים הובילו לשינויים מיידיים", "סותר ''prompted immediate policy changes''"]}', 1.05, 1.0, 0.25, 4, 'ai', NULL, true),
('97e38c66-6992-40e2-8fbe-0ff277fa8c98', 'restatement', 'Rarely does a single policy change produce such immediate and measurable results.', NULL, '[{"id": "a", "text": "This policy change produced no measurable results."}, {"id": "d", "text": "Policy changes always produce immediate results."}, {"id": "c", "text": "Measurable results are common after any policy change."}, {"id": "b", "text": "A single policy change produced unusually immediate and measurable results."}]'::jsonb, 3, '{"strategy": "rarely does X produce = נדיר ש-X מייצר. יוצא דופן.", "correct_reason": "אותה משמעות בדיוק: תוצאה חריגה בהיקפה ובמהירותה.", "options_analysis": ["סותר ''measurable results''", "הפוך — ''always'' סותר ''rarely''", "הפוך — ''common'' סותר ''rarely''", "נכון! אותה משמעות בדיוק: תוצאה חריגה ומהירה במיוחד"]}', 1.34, 1.0, 0.25, 4, 'ai', NULL, true),
('09a9e269-7f90-45fd-ad64-b72f8abf1310', 'reading_comprehension', 'What is the passage mainly about?', 'b57d36b4-cf91-486d-acf0-b779844a0912', '[{"id": "a", "text": "The widespread presence and potential health effects of microplastics"}, {"id": "b", "text": "How to manufacture plastic products"}, {"id": "d", "text": "The history of cosmetic products"}, {"id": "c", "text": "Why oceans are the only source of pollution"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את התפשטות המיקרופלסטיק והשפעותיו הבריאותיות האפשריות.", "correct_reason": "כל הפסקה עוסקת במקורות המיקרופלסטיק, בהתפשטותו ובמחקר על השפעותיו.", "options_analysis": ["נכון! ההתפשטות וההשפעות הבריאותיות האפשריות = הנושא הכולל", "לא הוראות ייצור, אלא ניתוח סביבתי", "פרט משני שמוזכר כמקור, לא הנושא הכולל", "לא נאמר בפסקה — מקורות נוספים מוזכרים גם"]}', 1.22, 1.0, 0.25, 4, 'ai', NULL, true),
('6e65fb64-d7db-4692-bd0a-1556bf88cf01', 'reading_comprehension', 'According to the passage, what are two sources of microplastics?', 'b57d36b4-cf91-486d-acf0-b779844a0912', '[{"id": "a", "text": "Only metal particles"}, {"id": "c", "text": "Synthetic fibers from clothing and cosmetic beads"}, {"id": "b", "text": "Only glass fragments"}, {"id": "d", "text": "Only volcanic ash"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את המקורות המוזכרים בפסקה.", "correct_reason": "הפסקה אומרת: ''synthetic fibers shed from clothing during washing, and tiny plastic beads once commonly used in cosmetic products''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.18, 1.0, 0.25, 4, 'ai', NULL, true),
('3882b617-4623-449b-88a1-db47ad617f9a', 'reading_comprehension', 'The word "persist" in the passage most closely means:', 'b57d36b4-cf91-486d-acf0-b779844a0912', '[{"id": "c", "text": "dissolve in water immediately"}, {"id": "a", "text": "disappear quickly"}, {"id": "b", "text": "continue to exist for a long time"}, {"id": "d", "text": "change color rapidly"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''they persist in the environment for extremely long periods''.", "correct_reason": "persist = להתמיד/להמשיך להתקיים לאורך זמן.", "options_analysis": ["לא קשור למשמעות המילה, וגם סותר ''chemically stable''", "הפוך גמור למשמעות המילה", "נכון! persist = להמשיך להתקיים לאורך זמן", "לא קשור למשמעות המילה"]}', 0.98, 1.0, 0.25, 4, 'ai', NULL, true),
('8a98f390-58b8-4e23-8b1e-2e7862a45046', 'reading_comprehension', 'Where have microplastics been detected in the human body, according to the passage?', 'b57d36b4-cf91-486d-acf0-b779844a0912', '[{"id": "b", "text": "They have never been detected in humans"}, {"id": "a", "text": "Only in hair"}, {"id": "c", "text": "Only in fingernails"}, {"id": "d", "text": "Blood, lung tissue, and placentas"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את המיקומים בגוף האדם שמוזכרים בפסקה.", "correct_reason": "הפסקה אומרת: ''these particles have now been detected in human blood, lung tissue, and even placentas''.", "options_analysis": ["סותר את הפסקה — הם כן זוהו בבני אדם", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.11, 1.0, 0.25, 4, 'ai', NULL, true),
('2e784b23-c726-439b-9737-29d790df2db5', 'reading_comprehension', 'What have several countries done in response to concerns about microplastics, according to the passage?', 'b57d36b4-cf91-486d-acf0-b779844a0912', '[{"id": "a", "text": "Banned microbeads in cosmetics"}, {"id": "b", "text": "Banned all plastic products entirely"}, {"id": "c", "text": "Required warning labels on all clothing"}, {"id": "d", "text": "Stopped all scientific research on the topic"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הצעד שננקט לפי הפסקה.", "correct_reason": "הפסקה אומרת: ''several countries have banned microbeads in cosmetics''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה — הפעולה ספציפית יותר", "לא נאמר בפסקה", "סותר את הפסקה — המחקר דווקא נמשך"]}', 1.26, 1.0, 0.25, 4, 'ai', NULL, true);